function renderClassifier(){const list=$('classifyList');list.replaceChildren();cards.forEach((card,i)=>{const item=document.createElement('article');item.className='quiz-card';const typ=document.createElement('small');typ.textContent=card.type;const h=document.createElement('h3');h.textContent=`${String(i+1).padStart(2,'0')}. ${card.name}`;const buttons=document.createElement('div');buttons.className='quiz-options';const feedback=document.createElement('div');feedback.className='feedback';feedback.setAttribute('aria-live','polite');for(const [key,name] of Object.entries(categories)){const b=document.createElement('button');b.type='button';b.textContent=name;b.setAttribute('aria-pressed',String(answers[i]===key));if(answers[i]!==undefined){b.disabled=true;if(answers[i]===key)b.classList.add('selected');}b.addEventListener('click',()=>{if(answers[i]!==undefined)return;answers[i]=key;renderClassifier();});buttons.append(b);}if(answers[i]){const correct=answers[i]===card.category;feedback.classList.add(correct?'good':'bad');feedback.textContent=(correct?'✓ Correcto. ':'✕ Corresponde a '+categories[card.category]+'. ')+card.why;}item.append(typ,h,buttons,feedback);list.append(item);});const done=Object.keys(answers).length;const score=Object.entries(answers).filter(([i,v])=>cards[Number(i)].category===v).length;$('quizProgress').textContent=`${done} / ${cards.length} resueltas`;$('quizScore').textContent=`${score} aciertos de ${done}`;}
