function renderRoutes(){const buttons=$('routeButtons');buttons.replaceChildren();routes.forEach((r,i)=>{const b=document.createElement('button');b.textContent=r.label;b.type='button';b.classList.toggle('active',i===selectedRoute);b.setAttribute('aria-pressed',String(i===selectedRoute));b.addEventListener('click',()=>{selectedRoute=i;selectedStep=0;renderRoutes();});buttons.append(b);});const flow=$('routeFlow');flow.replaceChildren();routes[selectedRoute].steps.forEach((step,i)=>{const wrap=document.createElement('div');wrap.className='flow-step';const b=document.createElement('button');b.textContent=step[0];b.type='button';b.classList.toggle('active',i===selectedStep);b.setAttribute('aria-pressed',String(i===selectedStep));b.addEventListener('click',()=>{selectedStep=i;renderRoutes();});wrap.append(b);if(i<routes[selectedRoute].steps.length-1){const arrow=document.createElement('span');arrow.className='flow-arrow';arrow.setAttribute('aria-hidden','true');arrow.textContent='→';wrap.append(arrow);}flow.append(wrap);});$('stepInfo').replaceChildren();const h=document.createElement('h3');h.textContent=routes[selectedRoute].steps[selectedStep][0];const p=document.createElement('p');p.textContent=routes[selectedRoute].steps[selectedStep][1];$('stepInfo').append(h,p);}
