function renderGenCycleCompare(){const root=$('genCycleCompare');root.replaceChildren();const y=genSelectedYear();if(y===2022){root.innerHTML='<p class="gen-unavailable">Dato no disponible: comparación de tecnologías 2022 pendiente de validación.</p>';return;}const a=CFE_TECH[0]['v'+y],b=CFE_TECH[3]['v'+y];const div=document.createElement('div');div.className='gen-compare-rows';for(const [label,v] of [['Ciclo combinado',a],['Vapor convencional',b]]){const row=document.createElement('div');row.className='gen-compare-row';const l=document.createElement('span');l.textContent=label;const val=document.createElement('strong');val.textContent=genNum(v)+' GWh';row.append(l,genBar(v,Math.max(a,b)),val);div.append(row);}const p=document.createElement('p');p.className='gen-small-hint';p.textContent=`En ${y} se reportaron ${genNum(a-b)} GWh más de ciclo combinado que de vapor convencional (diferencia calculada).`;root.append(div,p);}
