const TX_SERIES={2022:{km:110449,stations:2279,mva:165541,page:'2022 · p. 124'},2023:{km:110559,stations:2302,mva:164992,page:'2023 · p. 116'},2024:{km:111138,stations:2317,mva:168981,page:'2024 · p. 76'}};
const txNum=(n,digits=2)=>new Intl.NumberFormat('es-MX',{maximumFractionDigits:digits}).format(n);
function renderTxHistory(){const year=Number($('txYear').value),t=TX_SERIES[year],prev=TX_SERIES[year-1];$('txLines').textContent=txNum(t.km,0)+' km';$('txStations').textContent=txNum(t.stations,0);$('txMva').textContent=txNum(t.mva,0)+' MVA';$('txDelta').textContent=prev?'+'+txNum(t.km-prev.km,0)+' km':'Dato no disponible';const root=$('txBars');root.replaceChildren();for(const y of [2022,2023,2024]){const row=document.createElement('div');row.className='tx-bar-row'+(year===y?' is-active':'');const label=document.createElement('b');label.textContent=y;const track=document.createElement('div');track.className='tx-bar-track';const fill=document.createElement('div');fill.className='tx-bar-fill';fill.style.width=(100*TX_SERIES[y].km/111138)+'%';track.append(fill);const val=document.createElement('strong');val.textContent=txNum(TX_SERIES[y].km,0)+' km';row.append(label,track,val);root.append(row)}root.setAttribute('aria-label','CFE Transmisión: 2022 110449 kilómetros; 2023 110559 kilómetros; 2024 111138 kilómetros.');}
function txValidate(){const p=Number($('txPower').value),v=Number($('txVoltage').value),r=Number($('txResistance').value),pf=Number($('txPf').value);const vals=[$('txPower').value,$('txVoltage').value,$('txResistance').value,$('txPf').value];if(vals.some(x=>x.trim()==='')||![p,v,r,pf].every(Number.isFinite))return{err:'Completa todos los campos con valores numéricos.'};if(p<=0||p>100000)return{err:'La potencia debe ser mayor que 0 y no superar 100,000 MW.'};if(v<=0||v>1000)return{err:'La tensión debe ser mayor que 0 y no superar 1,000 kV.'};if(r<0||r>100000)return{err:'La resistencia equivalente debe ser mayor o igual a 0 Ω.'};if(pf<=0||pf>1)return{err:'El factor de potencia debe estar entre 0 (excluido) y 1 (incluido).'};return{p,v,r,pf}}
function txCalculate({p,v,r,pf}){const current=p*1e6/(Math.sqrt(3)*v*1000*pf),loss=3*current*current*r/1e6;return{current,loss,pct:loss/p*100,remaining:p-loss};}
function renderTxSimulation(){const inputs=txValidate(),error=$('txError');if(inputs.err){error.hidden=false;error.textContent=inputs.err;for(const id of ['txCurrent','txLoss','txLossPct','txRemaining'])$(id).textContent='—';$('txSweep').replaceChildren();$('txResultNote').textContent='Ajusta las entradas para obtener un resultado válido.';return;}error.hidden=true;const o=txCalculate(inputs);$('txCurrent').textContent=txNum(o.current);$('txLoss').textContent=txNum(o.loss,4);$('txLossPct').textContent=txNum(o.pct,3);$('txRemaining').textContent=txNum(o.remaining,4);$('txResultNote').textContent=o.loss>=inputs.p?'Advertencia: las pérdidas igualan o superan P. Este escenario no es físicamente representativo dentro del modelo simplificado.':'Simulación idealizada: las pérdidas resistivas NO equivalen a las pérdidas oficiales de CFE.';
 const pairs=[69,115,230,400].map(v=>({v,loss:txCalculate({...inputs,v}).loss}));const max=Math.max(...pairs.map(x=>x.loss),1e-15);const sweep=$('txSweep');sweep.replaceChildren();for(const one of pairs){const row=document.createElement('div');row.className='tx-sweep-row'+(Math.abs(one.v-inputs.v)<1e-9?' selected':'');const name=document.createElement('b');name.textContent=one.v+' kV';const track=document.createElement('div');track.className='tx-sweep-track';const fill=document.createElement('div');fill.className='tx-sweep-fill';fill.style.width=(one.loss/max*100)+'%';track.append(fill);const result=document.createElement('strong');result.textContent=txNum(one.loss,4)+' MW';row.append(name,track,result);sweep.append(row)}sweep.setAttribute('aria-label',pairs.map(x=>x.v+' kV: '+txNum(x.loss,4)+' MW de pérdidas calculadas').join('; '));}
function initTx(){if(!$('txYear'))return;$('txYear').addEventListener('change',renderTxHistory);for(const id of ['txPower','txVoltage','txResistance','txPf'])$(id).addEventListener('input',renderTxSimulation);document.querySelectorAll('[data-tx-preset]').forEach(btn=>btn.addEventListener('click',()=>{$('txVoltage').value=btn.dataset.txPreset;renderTxSimulation()}));$('txReset').addEventListener('click',()=>{$('txPower').value=100;$('txVoltage').value=230;$('txResistance').value=1;$('txPf').value=1;renderTxSimulation()});renderTxHistory();renderTxSimulation();}
