const distNum=(n,decimals=2)=>new Intl.NumberFormat('es-MX',{maximumFractionDigits:decimals,minimumFractionDigits:decimals}).format(n);
function renderDistribution(){const year=Number($('distYear').value),d=DIST_HISTORY[year],key=$('distMetric').value,m=DIST_METRIC[key];$('distSaidi').innerHTML=distNum(d.saidi,3)+' <span>min</span>';$('distSaifi').innerHTML=distNum(d.saifi,3)+' <span>int/cliente</span>';$('distLossAll').innerHTML=distNum(d.lossAll,2)+' <span>%</span>';$('distLossMt').innerHTML=distNum(d.lossMt,2)+' <span>%</span>';$('distPlotTitle').textContent=m.label;const root=$('distBars');root.replaceChildren();const max=Math.max(...Object.values(DIST_HISTORY).map(x=>x[key]));for(const y of [2022,2023,2024]){const row=document.createElement('div');row.className='dist-bar-row'+(year===y?' is-active':'');const label=document.createElement('b');label.textContent=y;const track=document.createElement('div');track.className='dist-bar-track';const fill=document.createElement('div');fill.className='dist-bar-fill';fill.style.width=(100*DIST_HISTORY[y][key]/max)+'%';track.append(fill);const val=document.createElement('strong');val.textContent=distNum(DIST_HISTORY[y][key],m.decimals)+' '+m.unit;row.append(label,track,val);root.append(row)}root.setAttribute('aria-label',m.label+': '+[2022,2023,2024].map(y=>y+', '+distNum(DIST_HISTORY[y][key],m.decimals)+' '+m.unit).join('; '));$('distPlotCaption').textContent='Datos históricos oficiales de CFE, Informe Anual 2024, p. 96. Cada barra utiliza una escala relativa al valor máximo de esta serie, no parte de una referencia arbitraria.';}
function distValidate(){const fields=['distVp','distNp','distNs','distIp'];if(fields.some(id=>$(id).value.trim()===''))return{error:'Completa los cuatro campos.'};const [vp,np,ns,ip]=fields.map(id=>Number($(id).value));if(![vp,np,ns,ip].every(Number.isFinite))return{error:'Utiliza únicamente números finitos.'};if(vp<=0||vp>1e6)return{error:'La tensión primaria debe ser mayor que 0 V y menor o igual a 1,000,000 V.'};if(!Number.isSafeInteger(np)||np<1||np>1e7||!Number.isSafeInteger(ns)||ns<1||ns>1e7)return{error:'Las cantidades de espiras deben ser números enteros entre 1 y 10 millones.'};if(ip<0||ip>1e6)return{error:'La corriente primaria debe estar entre 0 A y 1,000,000 A.'};return{vp,np,ns,ip};}
function distCalculate({vp,np,ns,ip}){const vs=vp*ns/np,is=ip*np/ns,va=vp*ip,ratio=np/ns;return{vs,is,va,ratio};}
function renderDistTransformer(){const input=distValidate(),error=$('distError');if(input.error){error.textContent=input.error;error.hidden=false;for(const id of ['distVs','distIs','distVa','distRatio'])$(id).textContent='—';$('distResultNote').textContent='Corrige las entradas para obtener resultados.';$('distVisualPrimary').textContent='—';$('distVisualSecondary').textContent='—';return;}const out=distCalculate(input);if(![out.vs,out.is,out.va,out.ratio].every(Number.isFinite)){error.textContent='El resultado supera el rango numérico permitido.';error.hidden=false;return;}error.hidden=true;$('distVs').textContent=distNum(out.vs);$('distIs').textContent=distNum(out.is);$('distVa').textContent=distNum(out.va);$('distRatio').textContent=distNum(out.ratio,4);$('distVisualPrimary').textContent=distNum(input.vp)+' V';$('distVisualSecondary').textContent=distNum(out.vs)+' V';$('distResultNote').textContent=out.ratio>1?'Transformador reductor de tensión (modelo ideal).':out.ratio<1?'Transformador elevador de tensión (modelo ideal).':'Transformador 1:1: mismas tensiones (modelo ideal).';}
function initDistribution(){if(!$('distYear'))return;$('distYear').addEventListener('change',renderDistribution);$('distMetric').addEventListener('change',renderDistribution);for(const id of ['distVp','distNp','distNs','distIp'])$(id).addEventListener('input',renderDistTransformer);$('distStepDown').addEventListener('click',()=>{$('distVp').value='230';$('distNp').value='1000';$('distNs').value='100';$('distIp').value='2';renderDistTransformer()});$('distStepUp').addEventListener('click',()=>{$('distVp').value='120';$('distNp').value='100';$('distNs').value='500';$('distIp').value='2';renderDistTransformer()});$('distReset').addEventListener('click',()=>{$('distVp').value='230';$('distNp').value='1000';$('distNs').value='100';$('distIp').value='2';renderDistTransformer()});renderDistribution();renderDistTransformer();}
