let factsCategory='all'; let factSelected=1;
function showFact(id){const f=FACTS.find(x=>x.id===id);if(!f)return;factSelected=id;document.querySelectorAll('[data-fact-id]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.factId)===id)));$('factsDetailTitle').textContent=f.title+' · '+f.v+' '+f.unit;$('factsDetailBody').textContent=f.body;const m=$('factsDetailMeta');m.replaceChildren();for(const t of ['Dato oficial · '+f.year,f.scale,FACT_DOCS[f.doc].name+' · p. '+f.page]){const span=document.createElement('span');span.textContent=t;m.append(span)};const a=document.createElement('a');a.textContent='Consultar fuente institucional ↗';a.href=FACT_DOCS[f.doc].url;a.target='_blank';a.rel='noopener noreferrer';m.append(a)}
function renderFacts(){const root=$('factsCards');root.replaceChildren();const subset=FACTS.filter(x=>factsCategory==='all'||x.cat===factsCategory);for(const f of subset){const b=document.createElement('button');b.type='button';b.className='fact-card';b.dataset.factId=f.id;b.setAttribute('aria-pressed',String(f.id===factSelected));const top=document.createElement('div');top.className='fact-card-top';const number=document.createElement('span');number.textContent='#'+String(f.id).padStart(2,'0');const category=document.createElement('span');category.textContent=FACT_CATS[f.cat];top.append(number,category);const v=document.createElement('strong');v.className='fact-number';v.textContent=f.v+' '+f.unit;const title=document.createElement('span');title.className='fact-label';title.textContent=f.title;const meta=document.createElement('small');meta.textContent=f.year+' · '+f.scale;const src=document.createElement('small');src.className='fact-source';src.textContent=FACT_DOCS[f.doc].name+' · p. '+f.page;b.append(top,v,title,meta,src);b.addEventListener('click',()=>{showFact(f.id);if(window.matchMedia('(max-width:650px)').matches)$('factsDetail').scrollIntoView({behavior:'smooth',block:'start'})});root.append(b)}if(!subset.some(x=>x.id===factSelected))factSelected=subset[0]?.id;showFact(factSelected)}
const FACT_CHARTS={generation:{title:'Generación bruta CFE (GWh)',vals:[141342,150462,154059],units:'GWh',ref:'CFE, Informes Anuales 2023 (p. 15) y 2024 (p. 24). Serie institucional, no generación nacional.'},lines:{title:'Red de transmisión CFE (km)',vals:[110449,110559,111138],units:'km',ref:'CFE, Informes Anuales 2022 (p. 124), 2023 (p. 116) y 2024 (p. 76). Para 2023, la edición 2024 cita 110,558 km.'},saidi:{title:'SAIDI de distribución (min/cliente)',vals:[19.248,17.788,16.708],units:'min/cliente',ref:'CFE, Informe Anual 2024, p. 96, tablero de indicadores de distribución.'},loss:{title:'Pérdidas que incluyen alta tensión (%)',vals:[11.05,10.86,10.69],units:'%',ref:'CFE, Informe Anual 2024, p. 96. No confundir con el indicador MT+BT.'}};
function renderFactsChart(){const d=FACT_CHARTS[$('factsChartSelect').value],root=$('factsChart');$('factsChartTitle').textContent=d.title;$('factsChartSource').textContent=d.ref;root.replaceChildren();let max=Math.max(...d.vals);d.vals.forEach((n,i)=>{const row=document.createElement('div');row.className='facts-chart-row';const label=document.createElement('b');label.textContent=String(2022+i);const bar=document.createElement('div');bar.className='facts-chart-track';const fill=document.createElement('div');fill.className='facts-chart-fill';fill.style.width=String(100*n/max)+'%';bar.append(fill);const val=document.createElement('strong');val.textContent=new Intl.NumberFormat('es-MX',{maximumFractionDigits:3}).format(n)+' '+d.units;row.append(label,bar,val);root.append(row)});root.setAttribute('aria-label',d.title+': '+d.vals.map((x,i)=>`${2022+i}: ${x} ${d.units}`).join('; '))}
const LAW_EVENTS=[
 {date:'20 dic 2013',title:'Reforma constitucional en materia de energía',body:'El decreto reformó los artículos 25, 27 y 28 de la Constitución durante el gobierno de Enrique Peña Nieto. Conservó el control estatal de la planeación del SEN y del servicio público de transmisión y distribución, mientras estableció las bases constitucionales del nuevo régimen energético.',url:'https://www.dof.gob.mx/nota_detalle.php?codigo=5327463&fecha=20/12/2013',ref:'DOF · 20/12/2013 · Decreto de reforma constitucional energética'},
 {date:'11 ago 2014',title:'Legislación secundaria del nuevo marco',body:'Se expidió la Ley de la Industria Eléctrica, que reguló generación, comercialización, transmisión, distribución y funcionamiento del mercado eléctrico. También se publicó la Ley de la Comisión Federal de Electricidad, con un régimen de empresa productiva del Estado.',url:'https://interconexion.cfe.mx/marcoregulatorio/Leyes/Ley%20de%20la%20Industria%20Electrica.pdf',ref:'DOF · 11/08/2014 · Ley de la Industria Eléctrica y leyes complementarias'},
 {date:'31 oct 2024',title:'Reforma constitucional de áreas y empresas estratégicas',body:'El decreto modificó los artículos 25, 27 y 28. Introdujo referencias expresas a empresas públicas del Estado y precisó la planeación, el control del sistema eléctrico y el servicio público de transmisión y distribución dentro de las áreas estratégicas.',url:'https://sidof.segob.gob.mx/notas/5742012',ref:'DOF · 31/10/2024 · Decreto en materia de áreas y empresas estratégicas'},
 {date:'18 mar 2025',title:'Nuevas leyes del sector eléctrico y de CFE',body:'Se publicaron la Ley del Sector Eléctrico y la Ley de la Empresa Pública del Estado, Comisión Federal de Electricidad. El marco reorganizó la naturaleza jurídica de CFE y reemplazó disposiciones de las leyes de 2014 conforme a sus artículos transitorios.',url:'https://sidof.segob.gob.mx/notas/5752329',ref:'DOF · 18/03/2025 · Decreto de nuevas leyes energéticas'}
];
function showLaw(i){const l=LAW_EVENTS[i];$('factsLawTitle').textContent=l.date+' · '+l.title;$('factsLawBody').textContent=l.body;const root=$('factsLawSource');root.replaceChildren();const a=document.createElement('a');a.href=l.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=l.ref+' ↗';root.append(a);document.querySelectorAll('[data-law-index]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.lawIndex)===i)))}
function initFacts(){if(!$('factsCards'))return;document.querySelectorAll('[data-fact-category]').forEach(b=>b.addEventListener('click',()=>{factsCategory=b.dataset.factCategory;document.querySelectorAll('[data-fact-category]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderFacts()}));renderFacts();$('factsChartSelect').addEventListener('change',renderFactsChart);renderFactsChart();const root=$('factsTimeline');LAW_EVENTS.forEach((e,i)=>{const b=document.createElement('button');b.type='button';b.dataset.lawIndex=String(i);b.setAttribute('aria-pressed',String(i===0));const d=document.createElement('span');d.textContent=e.date;const title=document.createElement('strong');title.textContent=e.title;b.append(d,title);b.addEventListener('click',()=>showLaw(i));root.append(b)});showLaw(0)}
initFacts();
